#include <vector>
#include <algorithm>

class Solution {
public:
    int countReplacements(std::vector<int>& students) {
        int running_max = -2e9;
        int replacements = 0;
        for (int i = (int)students.size() - 1; i >= 0; --i) {
            if (students[i] < running_max) {
                replacements++;
            } else {
                running_max = students[i];
            }
        }
        return replacements;
    }
};

class Solution {
    public int countReplacements(int[] students) {
        int runningMax = Integer.MIN_VALUE;
        int replacements = 0;
        for (int i = students.length - 1; i >= 0; i--) {
            if (students[i] < runningMax) {
                replacements++;
            } else {
                runningMax = students[i];
            }
        }
        return replacements;
    }
}

